with w as (select customer_id,count(*) website_event_count,count(distinct session_id) session_count,max(event_timestamp) last_website_event from {{ ref('stg_website_events') }} group by customer_id), s as (select customer_id,count(*) support_ticket_count,sum(case when upper(status) not in ('CLOSED','RESOLVED') then 1 else 0 end) open_support_ticket_count,avg(resolution_time_minutes) avg_resolution_time_minutes from {{ ref('stg_support_tickets') }} group by customer_id), m as (select customer_id,sum(impression) marketing_impressions,sum(click) marketing_clicks,sum(conversion) marketing_conversions,sum(cost) marketing_cost from {{ ref('stg_marketing_events') }} group by customer_id) select c.customer_id,coalesce(w.website_event_count,0) website_event_count,coalesce(w.session_count,0) session_count,w.last_website_event,coalesce(s.support_ticket_count,0) support_ticket_count,coalesce(s.open_support_ticket_count,0) open_support_ticket_count,coalesce(s.avg_resolution_time_minutes,0) avg_resolution_time_minutes,coalesce(m.marketing_impressions,0) marketing_impressions,coalesce(m.marketing_clicks,0) marketing_clicks,coalesce(m.marketing_conversions,0) marketing_conversions,coalesce(m.marketing_cost,0) marketing_cost from {{ ref('stg_customers') }} c left join w on c.customer_id=w.customer_id left join s on c.customer_id=s.customer_id left join m on c.customer_id=m.customer_id
